document.addEventListener('DOMContentLoaded',()=>{const searchInput=document.getElementById('discoverSearch');const clearBtn=document.getElementById('clearFilters');searchInput?.addEventListener('keydown',(e)=>{if(e.key==='Enter'){e.preventDefault();searchInput.form?.submit()}});clearBtn?.addEventListener('click',()=>{if(clearBtn.dataset.clearUrl)window.location.href=clearBtn.dataset.clearUrl})})